            kind = "CURRENT"
            current_count += 1
        elif current_value == candidate_value:
            # 当前与候选独立收敛到同一值，与基线都不同。
            kind = "SAME"
            same_count += 1
        else:
            kind = "CONFLICT"
            conflict_count += 1
        changes.append(
            {
                "section": section,
                "base": base_fp,
                "current": current_fp,
                "target": target_fp,
                "kind": kind,
